class TimingMiddleware:
    def __init__(self, app):
        self.app = app

    def __call__(self, environ, start_response):
        t0 = time.perf_counter()
        def timed_start(status, headers, exc_info=None):        # response hook
            headers.append(('X-Time', f'{(time.perf_counter() - t0) * 1000:.1f}ms'))
            return start_response(status, headers, exc_info)
        return self.app(environ, timed_start)
app = TimingMiddleware(app)     # composed outermost-first
